    if (!util.settings.SHOW_UPDATE_TIME) {
        returnList = getAjaxJson(urlSeriesNovelsTitles(seriesID), true).body
        returnList.forEach(v => {
            v.title = v.title.trim()
            v.chapterUrl = urlNovel(v.id)
            novelIds.push(v.id)
        })
