//历史记录
function reportProcess(avid, cid) {
	const {java,cookie} = this;
    let csrf = cookie.getKey("https://www.bilibili.com","bili_jct");
    let url = "http://api.bilibili.com/x/v2/history/report";
    let body = "";
    if(cid){
       body = "aid="+avid+"&cid="+cid+"&csrf="+csrf+"&progress=0";
    }else{
        body = "aid="+avid+"&type=5&dt=2&csrf="+csrf
    }

    let headers = {
            Cookie: cookie.getCookie("https://www.bilibili.com")
     }

     url = url+","+JSON.stringify({
         "method":"POST",
         "body":body,
         "headers":headers
     })
    java.ajax(url)

}



function changeSearch(){
	   let char = ["综合排序","最多播放","最新发布","最多弹幕","最多收藏","最多评论"]

	   	switch(this.Map("searchselect")){
	   		case "🎥视频":
	   	     	return char
	   		case "📖专栏":
	   		     char[1] = "最多点击";
                    char.splice(3, 1);
                    char.splice(3, 1);
	   		     char.push("最多喜欢")
	   		     return char	   
	   		case "👤用户":
	   		     return ["默认","粉丝数","用户等级"]	   		
	   		 default:
	   		 return []		   	
	   		}	   		  	
}

function getSearchOrder(){
	switch(this.Map("searchorder")){
		case "最多播放":
		case "最多点击":
		return "click";
   case "粉丝数":
   return "fans";
   case "用户等级":
   return "level"   
		case "最新发布":
		return "pubdate";

		case "最多弹幕":
		return "dm";
   case "最多评论":
   return "scores";
   case "最多喜欢":
   return "attention";   
		case "最多收藏":
		return "stow";

		default:
		return "";

		}


	}

function changeM(t){
	const {java,book} = this;
	let type;
    let bookintro = String(book.intro);
	if(t == 0){
		type = /视 频/.test(this.Map("模式"))?"🎧 音 频":"🎥 视 频";
		type = /视频模式/.test(book.intro)?"🎧 音 频":"🎥 视 频";
		this.setHeaders("模式="+type);
    }else if(t==1){
			type = /视频/.test(this.Map("UP主"))?"📖 显示专栏":"🎬 显示视频";
			type = /显示视频/.test(bookintro)?"📖 显示专栏":"🎬 显示视频";
			this.setHeaders("UP主="+type);
		}
	java.refreshBookInfo()
	}


function showCom(bu){
	const {java,book,cache,chapter} = this;
    let hotu,newu,name = "";
    let bu = book?String(book.tocUrl):"";

	if(/v1\/detail/.test(bu)){
         hotu = this.getReply(bu.match(/id=(\d+)/)[1], 17, 3);
         newu = this.getReply(bu.match(/id=(\d+)/)[1], 17, 2);
    }else if(/article\/view/.test(bu)){
         hotu = this.getReply(bu.match(/\?id=(\d+)/)[1], 12, 3)
         newu = this.getReply(bu.match(/id=(\d+)/)[1], 12, 2);
    }else if(/opus\/detail/.test(bu)){
         hotu = this.getReply(book.getVariable("id"), 11, 3)
         newu = this.getReply(bu.match(/id=(\d+)/)[1], 11, 2);
    }else if(!/acc\/info/.test(bu)) {
        let aid = cache.get("comaid") || bu.match(/aid=(\d+)/)?.[1] || String(book.getVariable("aid"))
        if(aid){
             hotu = this.getReply(aid, 1, 3);
             newu = this.getReply(aid, 1, 2);
        }else{
            java.toast("详情页暂时无法加载评论\n请尝试进入视频后再查看评论")
        }



    }

